export interface McpAppInlinePreviewProps {
  /** Matched MCP App tool to preview. */
  match: McpAppToolRef;
  /** Original tool call's arguments/result, seeding the mounted app's initial state. */
  toolCall?: McpAppToolCallSeed;
  /** Shared cache (with a full-width canvas) so switching to it for this message reuses this preview's fetch instead of repeating it. */
  cache: McpAppResponseCache;
  /** This message's cache key (e.g. `mcpAppCanvasKey(index)`). */
  cacheKey: string;
  /** Host-supplied dependencies — display context, sandbox URL, and the resource-fetch/tool-call functions. */
  hostAdapter: McpAppHostAdapter;
  /** Called when the user activates the expand-to-canvas button. */
  onExpand: () => void;
  /** Accessible label for the expand-to-canvas button. */
  expandAriaLabel: string;
  /** Accessible label for the reload button. */
  reloadAriaLabel: string;
  /** Accessible name for the header's actions group. Defaults to `'MCP app actions'`. */
  actionsGroupAriaLabel?: string;
  /** Message shown when the resource fails to load or the app fails to initialize. */
  loadErrorLabel: string;
  /**
   * Whether this message's MCP App is currently open in the full-width
   * canvas. When `true`, the header stays (so the tool/app identity is still
   * visible) but the body shows `openedInCanvasLabel` centered instead of
   * mounting the app — only one live app instance exists at a time.
   */
  isOpenedInCanvas?: boolean;
  /** Message shown centered in the body when `isOpenedInCanvas` is `true`. */
  openedInCanvasLabel: string;
  /** Color overrides applied as CSS custom properties on the preview's root. */
  colors?: McpAppInlinePreviewColors;
}

useMcpAppInlinePreview = (
  match: McpAppToolRef | undefined,
  toolCall: McpAppToolCallSeed | undefined,
  cache: McpAppResponseCache,
  cacheKey: string,
  hostAdapter: McpAppHostAdapter,
  onRequestDisplayMode?: (mode: McpAppDisplayMode) => McpAppDisplayMode | void,
): McpAppInlinePreviewState => {
  const { hostContext, hostInfo, sandboxUrl, fetchResourceHtml, callTool } =
    hostAdapter;
  const [html, setHtml] = useState<string>();
  const [toolResult, setToolResult] = useState<CallToolResult>();
  /*
   * Lazy-initialized so an unconfigured sandbox never renders the loading
   * spinner for a frame before the effect below flips it to `Unavailable` —
   * `useEffect` runs after the browser paints, so seeding `Loading`
   * unconditionally here would flash the preview box even though it's about
   * to disappear.
   */
  const [status, setStatus] = useState<McpAppInlinePreviewStatus>(() =>
    match == null || sandboxUrl == null
      ? McpAppInlinePreviewStatus.Unavailable
      : McpAppInlinePreviewStatus.Loading,
  );
  const [reloadToken, setReloadToken] = useState(0);

  const reload = useCallback(() => {
    cache.invalidate(cacheKey);
    setReloadToken((n) => n + 1);
  }, [cache, cacheKey]);

  const loadPreview = useCallback(
    async (isCancelled: () => boolean) => {
      if (match == null || sandboxUrl == null) return;

      try {
        const seedKey = computeMcpAppSeedKey(toolCall);
        const { html: fetchedHtml, toolResult: resolvedResult } =
          await cache.getOrFetch(cacheKey, seedKey, async () => {
            const [html, toolResult] = await Promise.all([
              fetchResourceHtml(match.toolsetId, match.resourceUri),
              resolveMcpAppToolResult(match, toolCall, callTool),
            ]);
            return { html, toolResult };
          });
        if (isCancelled()) return;
        setHtml(fetchedHtml);
        setToolResult(resolvedResult);
        setStatus(McpAppInlinePreviewStatus.Ready);
      } catch {
        if (!isCancelled()) setStatus(McpAppInlinePreviewStatus.Error);
      }
    },
    [match, toolCall, sandboxUrl, cache, cacheKey, fetchResourceHtml, callTool],
  );

  useEffect(() => {
    if (match == null || sandboxUrl == null) {
      setStatus(McpAppInlinePreviewStatus.Unavailable);
      return;
    }

    let cancelled = false;
    setStatus(McpAppInlinePreviewStatus.Loading);
    void loadPreview(() => cancelled);

    return () => {
      cancelled = true;
    };
  }, [match, sandboxUrl, loadPreview, reloadToken]);

  const onToolCall = useCallback(
    async (name: string, args: unknown): Promise<CallToolResult> => {
      if (match == null) {
        throw new Error(`Tool call "${name}" failed: no matching MCP App`);
      }
      return callTool(match.toolsetId, name, args, match.kind);
    },
    [match, callTool],
  );

  if (
    status !== McpAppInlinePreviewStatus.Ready ||
    match == null ||
    sandboxUrl == null ||
    html == null
  ) {
    return { status, reload };
  }

  return {
    status,
    reload,
    content: {
      type: AttachmentContentType.McpApp,
      html,
      sandboxUrl,
      toolInput: toolCall?.toolInput,
      toolResult,
      hostContext,
      hostInfo,
      onToolCall,
      onRequestDisplayMode,
    },
  };
}

export interface McpAppInlinePreviewState {
  /** Current load state of the preview's fetch. */
  status: McpAppInlinePreviewStatus;
  /** Present only when `status` is `Ready`. */
  content?: McpAppCanvasContent;
  /** Re-fetches the resource and re-resolves the tool result from scratch, bypassing `cache`. */
  reload: () => void;
}

useMcpAppResponseCache = (
  conversationId: string,
): McpAppResponseCache => {
  const mapRef = useRef<Map<string, CacheEntry>>(new Map());
  const pendingRef = useRef<Map<string, Promise<CachedMcpAppResponse>>>(
    new Map(),
  );

  return useMemo<McpAppResponseCache>(() => {
    const namespacedKey = (key: string) => `${conversationId}:${key}`;
    const pendingKey = (key: string, seedKey: string | undefined) =>
      `${namespacedKey(key)}::${seedKey ?? ''}`;

    const get: McpAppResponseCache['get'] = (key, seedKey) => {
      const entry = mapRef.current.get(namespacedKey(key));
      if (entry == null) return undefined;
      if (entry.seedKey !== seedKey) return undefined;
      if (Date.now() - entry.cachedAt > CACHE_TTL_MS) return undefined;
      return { html: entry.html, toolResult: entry.toolResult };
    };

    const set: McpAppResponseCache['set'] = (key, value, seedKey) => {
      const now = Date.now();
      for (const [existingKey, existingEntry] of mapRef.current) {
        if (now - existingEntry.cachedAt > CACHE_TTL_MS) {
          mapRef.current.delete(existingKey);
        }
      }
      mapRef.current.set(namespacedKey(key), {
        ...value,
        seedKey,
        cachedAt: now,
      });
    };

    return {
      get,
      set,
      invalidate: (key) => {
        mapRef.current.delete(namespacedKey(key));
        const prefix = `${namespacedKey(key)}::`;
        for (const existingPendingKey of pendingRef.current.keys()) {
          if (existingPendingKey.startsWith(prefix)) {
            pendingRef.current.delete(existingPendingKey);
          }
        }
      },
      getOrFetch: (key, seedKey, fetchFn) => {
        const cached = get(key, seedKey);
        if (cached) return Promise.resolve(cached);

        const pKey = pendingKey(key, seedKey);
        let pending = pendingRef.current.get(pKey);
        if (!pending) {
          pending = fetchFn().then((result) => {
            set(key, result, seedKey);
            return result;
          });
          pendingRef.current.set(pKey, pending);
          /*
           * Chained on `pending` itself (not a separate `.catch`/`.then`), so
           * this runs only after the `set()` above has already happened on
           * success — closing the window between "fetch settled" and "cache
           * updated" during which a call arriving right then would find
           * neither the cache entry nor the (already-deleted) pending
           * promise and start a third, redundant fetch.
           */
          pending.finally(() => {
            pendingRef.current.delete(pKey);
          });
        }
        return pending;
      },
    };
  }, [conversationId]);
}

export interface McpAppToolRef {
  /** Id of the toolset/application this tool was discovered on. */
  toolsetId: string;
  /** The tool's declared `ui://` resource. */
  resourceUri: string;
  /** Name used to correlate this ref against a message's real tool-call data (`resolveMcpAppToolCallSeed`/`findMcpAppForMessage`). */
  toolName: string;
  /** The tool's real name as declared by its owning toolset's `tools/list` — what must be passed to the mounted app/`onToolCall`. */
  mcpToolName: string;
  /** Deployment kind — determines which host MCP proxy route resolves `tools/call` for this tool. */
  kind: McpDeploymentKind;
  /** How this tool was discovered — see `McpAppToolDiscovery`. */
  discovery: McpAppToolDiscovery;
}

export interface McpAppToolCallSeed {
  /** The tool call's real structured arguments. */
  toolInput?: Record<string, unknown>;
  /** The tool call's result, if already known. */
  toolResult?: CallToolResult;
}

export type FetchMcpAppResourceHtml = (
  toolsetId: string,
  resourceUri: string,
) => Promise<string>;

export type CallMcpAppTool = (
  toolsetId: string,
  toolName: string,
  args: unknown,
  kind: McpDeploymentKind,
) => Promise<CallToolResult>;

export interface CachedMcpAppResponse {
  /** The fetched resource's HTML body. */
  html: string;
  /** The tool call's resolved result, if any. */
  toolResult?: CallToolResult;
}

export interface McpAppResponseCache {
  /**
   * Returns the cached entry only if it was written for this exact
   * `seedKey` (`computeMcpAppSeedKey`) and is younger than the cache's TTL;
   * otherwise `undefined` (a miss), so a stale or seed-mismatched entry is
   * never served.
   */
  get: (
    key: string,
    seedKey: string | undefined,
  ) => CachedMcpAppResponse | undefined;
  /** Writes an entry for `key`, tagged with the seed it was resolved from. */
  set: (
    key: string,
    value: CachedMcpAppResponse,
    seedKey: string | undefined,
  ) => void;
  /** Removes the cached entry for `key`, if any. */
  invalidate: (key: string) => void;
  /**
   * Returns the fresh cached entry for `(key, seedKey)` if one exists
   * (same rules as `get`); otherwise runs `fetchFn` and caches its result.
   * Concurrent calls for the same `(key, seedKey)` before `fetchFn` settles
   * are coalesced onto the same in-flight promise instead of each starting
   * their own — without this, a component re-rendered before its first
   * fetch resolves (e.g. React StrictMode's dev-only double effect
   * invocation) would race two independent fetches/live tool re-calls for
   * the same message.
   */
  getOrFetch: (
    key: string,
    seedKey: string | undefined,
    fetchFn: () => Promise<CachedMcpAppResponse>,
  ) => Promise<CachedMcpAppResponse>;
}

export interface McpAppHostAdapter {
  /** `McpUiHostContext` to deliver to the mounted app's `ui/initialize` handshake. */
  hostContext: McpUiHostContext;
  /** Host identity (`name`/`version`) to deliver to the mounted app's `ui/initialize` handshake. */
  hostInfo: Implementation;
  /** Operator-configured MCP Apps sandbox-proxy URL, or `null` when unconfigured. */
  sandboxUrl: string | null;
  /** Fetches the matched tool's MCP Apps `ui://` resource. */
  fetchResourceHtml: FetchMcpAppResourceHtml;
  /** Forwards a tool call the mounted app makes on its own (`onToolCall`) or the live re-call `resolveMcpAppToolResult` performs. */
  callTool: CallMcpAppTool;
}

export enum McpAppInlinePreviewStatus {
  Loading = 'loading',
  Ready = 'ready',
  Error = 'error',
  Unavailable = 'unavailable',
}

collectToolCallNames = (messages: Message[]): Set<string> => {
  const names = new Set<string>();
  for (const message of messages) {
    for (const call of resolveToolCalls(
      message.custom_content?.state,
    ).values()) {
      names.add(call.name);
    }
  }
  return names;
}

findMcpAppForMessage = (
  message: Message,
  mcpAppTools: McpAppToolRef[],
  isStreaming: boolean,
): McpAppToolRef | undefined => {
  if (mcpAppTools.length === 0 || message.role !== MessageRole.Assistant) {
    return undefined;
  }
  const calledNames = new Set(
    [...resolveToolCalls(message.custom_content?.state).values()].map(
      (call) => call.name,
    ),
  );
  const matched = mcpAppTools.find((tool) => calledNames.has(tool.toolName));
  if (matched) return matched;
  const selfHosted = mcpAppTools.find((tool) => tool.discovery === 'direct');
  if (selfHosted) return selfHosted;
  return isStreaming ? mcpAppTools[0] : undefined;
}

resolveMcpAppToolCallSeed = (
  message: Message,
  toolName: string,
): McpAppToolCallSeed | undefined => {
  const state = message.custom_content?.state;
  if (!state) return undefined;

  const matched = [...resolveToolCalls(state).values()]
    .reverse()
    .find((call) => call.name === toolName);
  if (!matched) return undefined;

  return {
    toolInput: matched.args,
    toolResult:
      matched.result != null
        ? { content: [{ type: 'text', text: matched.result }] }
        : undefined,
  };
}

resolveMcpAppToolResult = async (
  match: McpAppToolRef,
  seed: McpAppToolCallSeed | undefined,
  callTool: CallMcpAppTool,
): Promise<CallToolResult | undefined> => {
  const isConfirmed = match.discovery === 'direct' || seed?.toolInput != null;
  if (!isConfirmed) {
    return seed?.toolResult;
  }

  try {
    return await callTool(
      match.toolsetId,
      match.mcpToolName,
      seed?.toolInput ?? {},
      match.kind,
    );
  } catch {
    return seed?.toolResult;
  }
}

MCP_APPS_CLASS = {
  /** The preview's bordered outer card. */
  preview: 'dial-mcp-apps-preview',
  /**
   * The header strip above the mounted app, holding the reload and
   * expand-to-canvas actions. It sits outside the app's own content, so a host
   * restyling it never overlaps what the app draws.
   */
  previewHeader: 'dial-mcp-apps-preview-header',
} as const

export interface McpAppInlinePreviewColors {
  /** Surface the mounted app sits on. Fallback: `--bg-layer-raised`. */
  previewBackground?: string;
  /** Border around the preview card. Fallback: `--stroke-tertiary`. */
  previewBorder?: string;
  /** Divider under the header strip. Fallback: `--stroke-tertiary`. */
  previewHeaderBorder?: string;
}

